public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nFresh mozzarella\nSan Marzano tomatoes\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F\n2. Roll out dough into a circle\n3. Spread crushed tomatoes evenly\n4. Tear mozzarella and distribute\n5. Bake for 10-12 minutes\n6. Top with fresh basil and drizzle olive oil", AverageRating = 4.5, RatingCount = 12 },
        new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted boiling water\n2. Crisp guanciale in a pan\n3. Whisk eggs with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately with extra pecorino", AverageRating = 4.8, RatingCount = 20 },
        new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or broil chicken until charred\n3. Sauté garlic and ginger in oil\n4. Add tomato sauce and spices, simmer\n5. Stir in cream and cooked chicken\n6. Simmer 10 minutes, serve with rice", AverageRating = 4.6, RatingCount = 15 },
        new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nGarlic\nEggs", Steps = "1. Soak rice noodles in warm water\n2. Make sauce: tamarind, fish sauce, sugar\n3. Stir-fry tofu until golden\n4. Scramble eggs in the pan\n5. Add noodles and sauce, toss\n6. Top with peanuts, bean sprouts, lime", AverageRating = 4.3, RatingCount = 8 },
        new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water, simmer\n3. Warm tortillas on a dry pan\n4. Fill tortillas with seasoned beef\n5. Top with lettuce, tomato, cheese\n6. Serve with sour cream and salsa", AverageRating = 4.2, RatingCount = 10 },
        new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Dice onion, tomato, jalapeño\n4. Mix all ingredients together\n5. Season with salt and lime juice\n6. Serve immediately with chips", AverageRating = 4.7, RatingCount = 18 },
        new() { Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold chocolate mixture into eggs\n4. Add flour and vanilla, fold gently\n5. Pour into greased ramekins\n6. Bake at 425°F for 12-14 minutes", AverageRating = 4.9, RatingCount = 25 },
        new() { Id = 8, Title = "Miso Soup", Category = "Asian", Ingredients = "Dashi stock\nWhite miso paste\nSilken tofu\nWakame seaweed\nGreen onions", Steps = "1. Bring dashi stock to a simmer\n2. Rehydrate wakame in water\n3. Cube tofu into small pieces\n4. Remove broth from heat\n5. Whisk in miso paste (don't boil)\n6. Add tofu, wakame, and sliced green onions", AverageRating = 4.1, RatingCount = 6 },
    };

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
